// A spec's compiled model (gotogether compile -spec; validate.CompileMBT)
// lets connect run where quint is not installed (ROADMAP Q1, DESIGN §110):
// its traces are generated by the Go evaluator's random simulation
// (qeval's Simulate, `quint run --mbt`'s semantics), and Config.Require,
// Step.Eval and a bound driver's check use its IR instead of a quint
// compile. GOTOGETHER_COMPILED says when, as for qtest's compiled
// checker:
//   - unset: where Config.Quint (quint) is not on PATH and the spec has a
//     compiled model at CompiledFor; quint, where it is, as before;
//   - "1": always, and the run fails where the spec has none;
//   - "0": never.
//
// Unset, a stale or unreadable compiled model beside the spec is passed
// over where quint runs, as it must be, and the run's log says so once a
// process, with the compile that refreshes it: a developer with quint
// would otherwise never see that the runs without quint (CI's) fail on
// it.
//
// Seeds cannot match quint's generator: the traces are other samples of
// the same model, valid by meaning (qeval's parity tests: each replays in
// quint, and quint's are paths of the evaluator's). Parity is the
// evaluator's, not the run's to check: no quint is asked. What the
// evaluator cannot simulate (a qeval.Unsupported: a fold whose result
// depends on quint's set order, an integer past 64 bits) fails the run
// with the construct and the fix, as does connect.Test (a quint test's
// run, which the evaluator does not run) and a Config.Args the
// simulation does not take; none falls back to quint unasked.

// MBTFormat is the format of a compiled model for connect (MBTModel).
const MBTFormat = mbtmodel.Format

// compiledEnv is qtest's switch, shared: one variable says whether a
// test without quint uses compiled models.
const compiledEnv = "GOTOGETHER_COMPILED"

// An MBTModel is a spec's main module compiled for connect, as its file
// holds it (gotogether compile -spec writes it): quint's IR with every
// definition of the main module kept, and what it was compiled from.
type MBTModel = mbtmodel.Model

// An MBTSource is one source of a compiled model: its path and sha256.
type MBTSource = mbtmodel.Source

// CompiledExt is the name's end of a compiled model kept by convention
// (CompiledFor): its gotogether.mbt/1 JSON in a gzip container, as a
// binding's is kept (validate.CompiledExt). LoadMBT reads the plain and
// the gzipped form alike; MBTModel.Write gzips a path ending in .gz, with
// the same bytes for the same model.
const CompiledExt = mbtmodel.Ext

// CompiledFor is where a spec's compiled model is kept by convention:
// beside the spec, its name's stem with CompiledExt (model/bank.qnt's is
// model/bank.mbt.json.gz), or with the main module's name between them
// when main is not the file's own (model/bank.bankDesign.mbt.json.gz).
// A plain .mbt.json an earlier gotogether kept there is not found: compile
// it again.
func CompiledFor(spec, main string) string { return mbtmodel.CompiledFor(spec, main) }

// LoadMBT reads a compiled model for connect, plain or gzipped, refusing
// a broken container, another format, a quint outside the admission
// policy and a stale artifact: a source present beside it whose sha256 is
// not the artifact's (an absent one is not checked: notes says so).
func LoadMBT(path string) (cm *MBTModel, notes []string, err error) { return mbtmodel.Load(path) }

func mainFlag(main string) string { return mbtmodel.MainFlag(main) }

// compiled is a run's compiled model: its file, and the Go evaluator's
// model of its IR, loaded once.
type compiled struct {
	path  string
	m     *qeval.Model
	notes []string
}

// compiledMode is c's compiled model per GOTOGETHER_COMPILED: nil where
// connect runs quint, an error where "1" asks for one the spec lacks or
// the one it has is refused. Where quint runs with the variable unset,
// ignored says what is wrong with the artifact beside the spec, if
// anything, for the run's log: which path runs does not depend on it.
func compiledMode(c Config, spec string) (cm *compiled, ignored *ignoredModel, err error) {
	path := CompiledFor(spec, c.Main)
	_, statErr := os.Stat(path)
	switch mode := os.Getenv(compiledEnv); mode {
	case "0":
		return nil, nil, nil
	case "1":
		if statErr != nil {
			plain := ""
			if p := mbtmodel.PlainBeside(path); p != "" {
				plain = fmt.Sprintf(" (%s is the plain form an earlier gotogether kept there: compile it again and remove it)", p)
			}
			return nil, nil, fmt.Errorf("connect: %s=1 generates traces from the spec's compiled model, and %s has none at %s (%v): compile it (gotogether compile -spec %s%s) where quint is installed%s",
				compiledEnv, c.Spec, path, statErr, c.Spec, mainFlag(c.Main), plain)
		}
	case "":
		if _, err := exec.LookPath(c.Quint); err == nil {
			return nil, ignoredFor(path, spec, c), nil
		}
		if statErr != nil {
			return nil, nil, nil
		}
	default:
		return nil, nil, fmt.Errorf("connect: %s=%q: want 1 (always the compiled model), 0 (never) or unset (where quint is not installed)", compiledEnv, mode)
	}
	cm, err = loadCompiled(path, spec, c)
	return cm, nil, err
}

// loadCompiled is the compiled model at path, checked to be of spec's
// c.Main, with the Go evaluator's model of its IR.
func loadCompiled(path, spec string, c Config) (*compiled, error) {
	cm, notes, err := LoadMBT(path)
	if err != nil {
		return nil, fmt.Errorf("connect: %w", err)
	}
	if abs, _ := filepath.Abs(filepath.Join(filepath.Dir(path), filepath.FromSlash(cm.Spec))); abs != spec || cm.Main != c.Main {
		return nil, fmt.Errorf("connect: compiled model %s is of %s (main %q), not of %s (main %q): compile it again (gotogether compile -spec %s%s)",
			path, cm.Spec, cm.Main, c.Spec, c.Main, c.Spec, mainFlag(c.Main))
	}
	m, err := qeval.Load(cm.IR)
	if err != nil {
		return nil, fmt.Errorf("connect: compiled model %s: the Go evaluator cannot read its IR: %w: compile it again with this gotogether", path, err)
	}
	return &compiled{path: path, m: m, notes: notes}, nil
}

// An ignoredModel is a compiled model a run with quint passes over and
// why ("" when it is current): checked once a process, logged once.
type ignoredModel struct {
	once   sync.Once
	why    string
	logged atomic.Bool
}

// ignoredModels are the artifacts runs with quint have checked, by path:
// process-wide, so that each is read and logged once a test binary.
var ignoredModels sync.Map // process-wide: path -> *ignoredModel

// ignoredFor is what a run with quint says of spec's (absolute) compiled
// model at path (CompiledFor's), nil where there is none: a refused one (stale, of
// another spec, unreadable) or a plain one an earlier gotogether kept,
// each with the fix. The check is the one a run without quint makes.
func ignoredFor(path, spec string, c Config) *ignoredModel {
	plain := mbtmodel.PlainBeside(path)
	if _, err := os.Stat(path); err != nil && plain == "" {
		return nil
	}
	v, _ := ignoredModels.LoadOrStore(path, &ignoredModel{})
	im := v.(*ignoredModel)
	im.once.Do(func() {
		var why []string
		if plain != "" {
			why = append(why, fmt.Sprintf("%s is a plain compiled model an earlier gotogether kept, which connect no longer finds (it reads %s): compile it again (gotogether compile -spec %s%s) and remove it",
				plain, filepath.Base(path), c.Spec, mainFlag(c.Main)))
		}
		if _, err := os.Stat(path); err == nil {
			if _, err := loadCompiled(path, spec, c); err != nil {
				why = append(why, strings.TrimPrefix(err.Error(), "connect: "))
			}
		}
		if len(why) > 0 {
			im.why = strings.Join(why, "; ")
		}
	})
	return im
}

// log writes why the compiled model is passed over to t's log, the first
// time a run of this process meets it.
func (im *ignoredModel) log(t testing.TB) {
	t.Helper()
	if im == nil || im.why == "" || !im.logged.CompareAndSwap(false, true) {
		return
	}
	t.Logf("connect: quint generates the traces here (%s unset), passing over the spec's compiled model, which a run without quint would use and refuse: %s", compiledEnv, im.why)
}

// RequireTraces skips the test unless c's traces can be generated here:
// quint is installed, or the spec has a compiled model connect uses
// instead (GOTOGETHER_COMPILED). It is the guard of a connect test that
// runs from its compiled model where quint is missing: use it where a test
// runs connect.Run or a bound driver's Run, in place of an
// exec.LookPath("quint") that skips, which never reaches the compiled
// model. Where quint runs, it logs a stale model beside the spec, as Run
// does.
func RequireTraces(t testing.TB, c Config) {
	t.Helper()
	c, err := c.FromEnv()
	if err != nil {
		t.Fatal(err)
	}
	if c.Quint == "" {
		c.Quint = "quint"
	}
	spec, err := filepath.Abs(c.Spec)
	if err != nil {
		t.Fatal(err)
	}
	cm, ignored, err := compiledMode(c, spec)
	if err != nil || cm != nil {
		return // a refused model fails the run, with its fix
	}
	ignored.log(t)
	if _, err := exec.LookPath(c.Quint); err != nil {
		plain := ""
		if p := mbtmodel.PlainBeside(CompiledFor(c.Spec, c.Main)); p != "" {
			plain = fmt.Sprintf("; %s is a plain one an earlier gotogether kept, which connect no longer finds: compile it again and remove it", p)
		}
		t.Skipf("quint not installed (npm i -g @informalsystems/quint), and %s has no compiled model at %s (gotogether compile -spec %s%s)%s",
			c.Spec, CompiledFor(c.Spec, c.Main), c.Spec, mainFlag(c.Main), plain)
	}
}

// simArgs are the invariants of c.Args, the one quint argument the Go
// simulation takes (--invariant a,b; --invariants); any other is refused,
// naming it: the simulation would not do what it asks.
func simArgs(args []string) ([]string, error) {
	var invs []string
	for i := 0; i < len(args); i++ {
		name, val, has := strings.Cut(args[i], "=")
		switch name {
		case "--invariant", "--invariants":
			if !has {
				if i+1 == len(args) {
					return nil, fmt.Errorf("connect: Config.Args %s names no invariant", name)
				}
				i++
				val = args[i]
			}
			for _, v := range strings.Split(val, ",") {
				if v = strings.TrimSpace(v); v != "" {
					invs = append(invs, v)
				}
			}
		default:
			return nil, fmt.Errorf("connect: Config.Args %q is quint's, and the compiled model's traces are the Go evaluator's, which takes --invariant alone: drop it, or run with quint (GOTOGETHER_COMPILED=0)", args[i])
		}
	}
	return invs, nil
}

// seedOf is quint's --seed (decimal, or hex with 0x) as the simulation's.
func seedOf(s string) (uint64, error) {
	if h, ok := strings.CutPrefix(strings.ToLower(s), "0x"); ok {
		return strconv.ParseUint(h, 16, 64)
	}
	return strconv.ParseUint(s, 10, 64)
}

// generateGo is GenerateRun on the compiled model: c.MaxSamples traces
// of the Go evaluator's simulation (trace i drawn from the seed and i, so
// one trace replays alone), each written as `quint run --mbt` writes one
// (run_<i>.itf.json in c.Dir: the variables, mbt::actionTaken and
// mbt::nondetPicks). A violated invariant fails the batch, as quint's
// run does, with the trace written.
func generateGo(ctx context.Context, c Config) ([]string, error) {
	stale, _ := filepath.Glob(filepath.Join(c.Dir, "run_*.itf.json"))
	for _, f := range stale {
		if err := os.Remove(f); err != nil {
			return nil, fmt.Errorf("removing an earlier run's trace: %w", err)
		}
	}
	invs, err := simArgs(c.Args)
	if err != nil {
		return nil, err
	}
	seed, err := seedOf(c.Seed)
	if err != nil {
		return nil, fmt.Errorf("connect: seed %q: %w: want a decimal or 0x hex integer", c.Seed, err)
	}
	m := c.compiled.m.WithContext(ctx)
	opt := qeval.SimOptions{Init: c.Init, Step: c.StepName, Steps: c.MaxSteps, Invariants: invs}
	if opt.Init == "" {
		opt.Init = "init"
	}
	if opt.Step == "" {
		opt.Step = "step"
	}
	if opt.Steps == 0 {
		opt.Steps = 20 // quint run's --max-steps
	}
	for _, n := range append([]string{opt.Init, opt.Step}, invs...) {
		if _, ok := m.Decl(n); !ok {
			return nil, fmt.Errorf("connect: %s has no definition %s (compiled model %s)", c.Spec, n, c.compiled.path)
		}
	}
	picks := map[string]bool{}
	for _, a := range []string{opt.Init, opt.Step} {
		for n := range m.Nondets(a) {
			picks[n] = true
		}
	}
	var files []string
	for i := range c.MaxSamples {
		if err := ctx.Err(); err != nil {
			return files, err
		}
		tr, err := m.Simulate(nil, opt, rand.New(rand.NewPCG(seed, uint64(i))))
		if err != nil {
			if u, ok := errors.AsType[*qeval.Unsupported](err); ok {
				return files, fmt.Errorf("connect: the Go evaluator cannot simulate %s (trace %d, seed %s): %s is outside its fragment: %s: run it with quint (install quint, or GOTOGETHER_COMPILED=0), or change the model", c.Spec, i, c.Seed, u.Op, u.Why)
			}
			if ee, ok := errors.AsType[*qeval.EvalError](err); ok {
				return files, fmt.Errorf("connect: %s fails in trace %d (seed %s): %s, the model's own error, as quint would report it", c.Spec, i, c.Seed, strings.TrimPrefix(ee.Error(), "qeval: "))
			}
			return files, fmt.Errorf("connect: simulating %s (trace %d, seed %s): %w", c.Spec, i, c.Seed, err)
		}
		f := filepath.Join(c.Dir, fmt.Sprintf("run_%d.itf.json", i))
		if err := writeMBT(f, m, opt, tr, picks, c, i); err != nil {
			return files, err
		}
		files = append(files, f)
		if tr.Violated != "" {
			return files, fmt.Errorf("connect: the Go evaluator's trace %d (seed %s) of %s violates invariant %s in its state %d (%s): fix the model, or drop the invariant from Config.Args",
				i, c.Seed, c.Spec, tr.Violated, len(tr.Steps), f)
		}
	}
	return files, nil
}

// writeMBT writes tr as `quint run --mbt` writes a trace: each state's
// variables (by their names in the spec), the action taken (the first
// state's init) and every pick of init and step, Some where the
// transition chose it and None elsewhere.
func writeMBT(path string, m *qeval.Model, opt qeval.SimOptions, tr *qeval.SimTrace, picks map[string]bool, c Config, index int) error {
	short := func(v string) string { return v[strings.LastIndex(v, ":")+1:] }
	vars := []string{}
	for _, v := range m.Vars {
		vars = append(vars, short(v))
	}
	vars = append(vars, "mbt::actionTaken", "mbt::nondetPicks")
	type state map[string]any
	states := []state{}
	add := func(s qeval.State, action string, chosen []qeval.Event) error {
		st := state{"#meta": map[string]any{"index": len(states)}}
		for _, v := range m.Vars {
			x, err := qeval.ToITF(s[v])
			if err != nil {
				return fmt.Errorf("connect: %s's value %s has no ITF form: %w", short(v), qeval.String(s[v]), err)
			}
			st[short(v)] = x
		}
		rec := map[string]itf.Value{}
		for n := range picks {
			rec[n] = itf.None()
		}
		for _, p := range chosen {
			x, err := qeval.ToITF(p.Value)
			if err != nil {
				return err
			}
			rec[p.Pick] = itf.VariantOf("Some", x)
		}
		st["mbt::actionTaken"] = action
		st["mbt::nondetPicks"] = rec
		states = append(states, st)
		return nil
	}
	if err := add(tr.Init.State, "init", tr.Init.Picks()); err != nil {
		return err
	}
	prev := tr.Init.State
	for _, t := range tr.Steps {
		a, err := m.ActionTaken(nil, prev, opt.Step, t)
		if err != nil {
			return err
		}
		if err := add(t.State, a, t.Picks()); err != nil {
			return err
		}
		prev = t.State
	}
	out := map[string]any{
		"#meta": map[string]any{"format": "ITF", "source": c.Spec,
			"description": fmt.Sprintf("written by gotogether's Go evaluator (connect, compiled model %s): trace %d of seed %s, quint run --mbt's semantics; no quint process", filepath.Base(c.compiled.path), index, c.Seed)},
		"vars":   vars,
		"states": states,
	}
	data, err := json.Marshal(out)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0o644)
}
